import { lazy, Suspense, type ReactNode } from 'react';

export type ThemeName = 'tenantry';

export const themeNames: ThemeName[] = ['tenantry'];

export type KcEnvName = 'TENANTRY_BASE_DOMAIN';

export const kcEnvNames: KcEnvName[] = ['TENANTRY_BASE_DOMAIN'];

